function TwoSum(nums: int[], target: int) -> int[] {
  let n = nums.length();
  let i = 0;
  while (i < n) {
    let j = i + 1;
    while (j < n) {
      if (nums[i] + nums[j] == target) {
        return [i, j];
      }
      j += 1;
    }
    i += 1;
  }
  return [];
}

